import React, { useState } from 'react';

const ConfiguracionPage = ({ asignaciones, onAddAsignacion, onDeleteAsignacion }) => {
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    grado: '',
    division: 'A',
    materia: '',
    turno: 'M',
  });

  // Opciones disponibles
  const grados = ['1', '2', '3', '4', '5', '6'];
  const divisiones = ['A', 'B', 'C', 'D'];
  const turnos = [
    { value: 'M', label: 'Mañana' },
    { value: 'T', label: 'Tarde' },
  ];
  const materias = [
    { id: 1, nombre: 'Matemática' },
    { id: 2, nombre: 'Lengua y Literatura' },
    { id: 3, nombre: 'Ciencias Naturales' },
    { id: 4, nombre: 'Ciencias Sociales' },
  ];

  const handleSubmit = (e) => {
    e.preventDefault();

    const materiaSeleccionada = materias.find(m => m.id === parseInt(formData.materia));

    const nuevaAsignacion = {
      id: Date.now(), // ID temporal
      grado: formData.grado,
      division: formData.division,
      turno: formData.turno,
      materia_id: parseInt(formData.materia),
      materia_nombre: materiaSeleccionada?.nombre || '',
    };

    onAddAsignacion(nuevaAsignacion);
    setFormData({ grado: '', division: 'A', materia: '', turno: 'M' });
    setShowForm(false);
  };

  const handleDelete = (id) => {
    if (window.confirm('¿Estás seguro de eliminar esta asignación?')) {
      onDeleteAsignacion(id);
    }
  };

  // Agrupar por grado-división
  const asignacionesAgrupadas = asignaciones.reduce((acc, asig) => {
    const key = `${asig.grado}° ${asig.division}`;
    if (!acc[key]) {
      acc[key] = { turno: asig.turno, materias: [] };
    }
    acc[key].materias.push(asig);
    return acc;
  }, {});

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Mis Asignaciones</h1>
          <p className="text-gray-600 mt-1">Configurá los grados, divisiones y materias que tenés a cargo</p>
        </div>
        <button
          onClick={() => setShowForm(true)}
          className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors flex items-center"
        >
          <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Agregar Asignación
        </button>
      </div>

      {/* Modal de formulario */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md mx-4">
            <h2 className="text-xl font-semibold mb-4">Nueva Asignación</h2>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Grado</label>
                  <select
                    value={formData.grado}
                    onChange={(e) => setFormData({ ...formData, grado: e.target.value })}
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  >
                    <option value="">Seleccionar</option>
                    {grados.map(g => (
                      <option key={g} value={g}>{g}° grado</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">División</label>
                  <select
                    value={formData.division}
                    onChange={(e) => setFormData({ ...formData, division: e.target.value })}
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  >
                    {divisiones.map(d => (
                      <option key={d} value={d}>{d}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Materia</label>
                <select
                  value={formData.materia}
                  onChange={(e) => setFormData({ ...formData, materia: e.target.value })}
                  required
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                >
                  <option value="">Seleccionar materia</option>
                  {materias.map(m => (
                    <option key={m.id} value={m.id}>{m.nombre}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Turno</label>
                <div className="flex gap-4">
                  {turnos.map(t => (
                    <label key={t.value} className="flex items-center">
                      <input
                        type="radio"
                        name="turno"
                        value={t.value}
                        checked={formData.turno === t.value}
                        onChange={(e) => setFormData({ ...formData, turno: e.target.value })}
                        className="mr-2"
                      />
                      {t.label}
                    </label>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setShowForm(false)}
                  className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Lista de asignaciones */}
      {Object.keys(asignacionesAgrupadas).length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
          <svg className="w-16 h-16 text-gray-300 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
          </svg>
          <h3 className="text-lg font-medium text-gray-900 mb-2">Sin asignaciones</h3>
          <p className="text-gray-500 mb-4">Agregá tu primer grado y materia para comenzar</p>
          <button
            onClick={() => setShowForm(true)}
            className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
          >
            Agregar Asignación
          </button>
        </div>
      ) : (
        <div className="grid gap-4">
          {Object.entries(asignacionesAgrupadas).map(([gradoDiv, data]) => (
            <div key={gradoDiv} className="bg-white rounded-xl border border-gray-200 p-6">
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">{gradoDiv}</h3>
                  <p className="text-sm text-gray-500">
                    Turno {data.turno === 'M' ? 'Mañana' : 'Tarde'}
                  </p>
                </div>
              </div>

              <div className="flex flex-wrap gap-2">
                {data.materias.map(asig => (
                  <div
                    key={asig.id}
                    className="flex items-center bg-gray-100 rounded-lg px-3 py-2"
                  >
                    <span className="text-gray-700">{asig.materia_nombre}</span>
                    <button
                      onClick={() => handleDelete(asig.id)}
                      className="ml-2 text-gray-400 hover:text-red-500"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ConfiguracionPage;
